import {readAutomation,readAutomationVersion,readAutomationLatest,createAutomation,reviseAutomation,activateAutomation,findAutomationByName} from './automation-editor-api'
import {newAutomationDraft,loadedAutomationDraft,automationDraftBody,automationPropertyTrigger,automationTriggerRow,automationPropertyTriggerType,automationPropertySourceSelection,automationSourceLabels,automationReportTriggers,automationReportTriggerConfig,automationReportTriggerValue,automationTargetAction,automationSceneRun,automationSceneSummary,automationScenePresentation,automationTaskRun,automationTaskSummary,automationTaskPresentation,automationCloudTransformAction,automationCloudOperationText,automationCloudAction,automationCloudPresentation,automationActionStyle,automationTriggerPresentation,automationActionPresentation,automationDeviceCondition,automationDeviceConditionAction,automationConditionPresentation,automationAlarmCondition,automationAlarmConditionAction,automationAlarmConditionPresentation,automationAlarmConditionSummary,automationCurrentConditionText,automationTimeCondition,automationTimeConditionAction,automationTimeConditionPresentation,automationTimeConditionSummary,automationSignature,cloneAutomationValue,assertAutomationContent,automationObject,automationOperatorLabels,automationDurationLabel,type AutomationBody,type AutomationDraft,type AutomationNode,type AutomationReportTrigger,type AutomationPropertyTriggerValue,type AutomationVersion} from './automation-editor-draft'
