const route=useRoute(),router=useRouter(),id=computed(()=>String(route.params.id||'')),editing=computed(()=>!!id.value)
const allowed=computed(()=>can('rule:manage')&&!!projectId.value),writable=computed(()=>allowed.value&&currentProject.value?.status==='ACTIVE')
const draft=ref<AutomationDraft>(newAutomationDraft()),step=ref(1),loading=ref(false),busy=ref(false),pending=ref(false),conflict=ref(false),error=ref(''),base=ref<Schema<'AutomationView'>>(),baseVersion=ref<AutomationVersion>()
const picker=ref<'trigger'|'condition'|'action'>(),triggerEditor=ref<{index?:number;config?:AutomationPropertyTriggerValue;kind?:AutomationMixedKind;options?:AutomationMixedTrigger['options'];enabled:boolean}>(),conditionEditor=ref<{index?:number;node?:AutomationNode;time?:boolean;alarm?:boolean}>(),actionEditor=ref<{index?:number;node?:AutomationNode;purpose?:'downlink'|'cloud-update'|'scene'|'task'}>(),names=ref(new Map<string,string>()),taskNames=ref(new Map<string,string>())
const triggerRows=computed(()=>automationReportTriggers(draft.value.triggerType,draft.value.triggerConfig))
