const pickerPresentation=computed(()=>picker.value==='trigger'?automationTriggerPresentation:picker.value==='condition'?automationConditionPresentation:automationActionPresentation)
const alarmNames=useAutomationAlarmRuleNames(()=>draft.value.conditions)
type Intent={mode:'create'|'atomic-edit';project:string;automationId?:string;body:AutomationBody;enabled:boolean;before:number;expectedFinalCAS:number;expectedStatus:'DRAFT'|'ACTIVE'|'PAUSED';previousVersionId?:string;previousActiveVersionId?:string|null;selectedVersionId?:string;stage:'definition'|'activation';stateSent:boolean}
const intent=ref<Intent>(),blocked=computed(()=>busy.value||pending.value||!!intent.value),formBlocked=computed(()=>!writable.value||loading.value||blocked.value||conflict.value)
let turn=0,alive=true,dragged=''
function current(token:number,project:string,epoch:number){return alive&&token===turn&&project===projectId.value&&epoch===identityEpoch()&&allowed.value}
function reset(){turn++;draft.value=newAutomationDraft();step.value=1;base.value=undefined;baseVersion.value=undefined;intent.value=undefined;picker.value=undefined;triggerEditor.value=undefined;conditionEditor.value=undefined;actionEditor.value=undefined;pending.value=false;busy.value=false;loading.value=false;conflict.value=false;error.value='';names.value=new Map();taskNames.value=new Map();dragged=''}
function sourceDevice(config:unknown){return automationObject(config)&&definitionUuid(config.deviceId)?config.deviceId:''}
async function load(){
 reset();if(!allowed.value||!editing.value)return
 const token=turn,project=projectId.value,epoch=identityEpoch(),automation=id.value;loading.value=true
 try{
  const first=await readAutomation(project,automation)
