  if(devices.length){try{const values=await selectedTaskChoices(project,'devices',devices);if(current(token,project,epoch))names.value=new Map(values.map(row=>[row.id,row.label]))}catch{/* 不可读名称保真实标识，不转换旧配置。 */}}
