 else if(intent.value){const held=intent.value;draft.value={tags:sourceRuleTagRows(held.body.tags===undefined?{}:held.body.tags),name:held.body.name,description:held.body.description??'',enabled:held.enabled,triggerType:held.body.triggerType,triggerConfig:cloneAutomationValue(held.body.triggerConfig),conditions:cloneAutomationValue(held.body.conditions),actions:cloneAutomationValue(held.body.actions).map(node=>({key:crypto.randomUUID(),node}))};pending.value=true;error.value='原自动化保存结果仍待核对；未重复提交。'}
 else void load()
