  const value=automationReportTriggerConfig(next,draft.value.triggerConfig);draft.value.triggerType=automationPropertyTriggerType(value);draft.value.triggerConfig=value;names.value=new Map(names.value).set(found.deviceId,name);triggerEditor.value=undefined;error.value=''
 }catch(cause){error.value=errorMessage(cause)}
}
function commitMixedTrigger(row:AutomationMixedTrigger,index?:number){
 const old=mixed.value,rows=old?.triggers??(draft.value.triggerType?automationReportAsMixed(draft.value.triggerType,draft.value.triggerConfig):[])
