function mixedTriggerSummary(row:AutomationMixedTrigger){if(row.kind!=='PROPERTY_REPORTED'&&row.kind!=='PROPERTY_CHANGED')return automationMixedSummary(row);const report=automationTriggerRow(row.options,row.enabled);return report?reportTriggerSummary(report):''}
function changeTriggerEnabled(index:number,enabled:string|number|boolean){
 if(mixed.value){if(formBlocked.value||typeof enabled!=='boolean'||!mixed.value.triggers[index])return;const rows=cloneAutomationValue(mixed.value.triggers);rows[index]={...rows[index]!,enabled};draft.value.triggerConfig=automationMixedValue(rows,mixed.value);return}
