}
function removeTrigger(index?:number){
 if(formBlocked.value)return
 if(index===undefined){draft.value.triggerType=undefined;draft.value.triggerConfig=undefined;return}
 if(mixed.value){const next=cloneAutomationValue(mixed.value.triggers);if(!next[index])return;next.splice(index,1);if(next.length)draft.value.triggerConfig=automationMixedValue(next,mixed.value);else{draft.value.triggerType=undefined;draft.value.triggerConfig=undefined}return}
 const rows=triggerRows.value;if(!rows?.[index])return
 try{const next=cloneAutomationValue(rows);next.splice(index,1);if(next.length)draft.value.triggerConfig=automationReportTriggerConfig(next,draft.value.triggerConfig);else{draft.value.triggerType=undefined;draft.value.triggerConfig=undefined}}catch(cause){error.value=errorMessage(cause)}
}

function chooseCondition(time=false){if(!formBlocked.value){picker.value=undefined;conditionEditor.value={time}}}
function chooseAlarmCondition(){if(!formBlocked.value){picker.value=undefined;conditionEditor.value={alarm:true}}}
function editCondition(index:number){const node=draft.value.conditions[index];if(!formBlocked.value&&node&&(automationDeviceCondition(node)||automationTimeCondition(node)||automationAlarmCondition(node)))conditionEditor.value={index,node:cloneAutomationValue(node),time:!!automationTimeCondition(node),alarm:!!automationAlarmCondition(node)}}
function saveCondition(node:AutomationNode,name:string){
 const editor=conditionEditor.value,config=automationDeviceCondition(node);if(!editor||formBlocked.value||!config||editor.index===undefined&&draft.value.conditions.length>=32)return
