}
function saveTimeCondition(node:AutomationNode){const editor=conditionEditor.value;if(formBlocked.value||!editor?.time||!automationTimeCondition(node)||editor.index===undefined&&draft.value.conditions.length>=32)return;if(editor.index===undefined)draft.value.conditions.push(cloneAutomationValue(node));else draft.value.conditions.splice(editor.index,1,cloneAutomationValue(node));conditionEditor.value=undefined;error.value=''}
function saveAlarmCondition(node:AutomationNode,deviceName:string,ruleName:string){const editor=conditionEditor.value,config=automationAlarmCondition(node);if(formBlocked.value||!editor?.alarm||!config||editor.index===undefined&&draft.value.conditions.length>=32)return;if(editor.index===undefined)draft.value.conditions.push(cloneAutomationValue(node));else draft.value.conditions.splice(editor.index,1,cloneAutomationValue(node));names.value=new Map(names.value).set(config.deviceId,deviceName);alarmNames.value=new Map(alarmNames.value).set(config.alarmRuleId,ruleName);conditionEditor.value=undefined;error.value=''}
function conditionEnabled(node:AutomationNode){return automationDeviceCondition(node)?.enabled??automationTimeCondition(node)?.enabled??automationAlarmCondition(node)?.enabled}
function conditionPresentation(node:AutomationNode){return automationAlarmCondition(node)?automationAlarmConditionPresentation:automationTimeCondition(node)?automationTimeConditionPresentation:automationConditionPresentation}
function changeConditionEnabled(index:number,enabled:string|number|boolean){const node=draft.value.conditions[index];if(formBlocked.value||typeof enabled!=='boolean'||!node)return;const time=automationTimeCondition(node),config=automationDeviceCondition(node),alarm=automationAlarmCondition(node);if(alarm)draft.value.conditions.splice(index,1,automationAlarmConditionAction({...alarm,enabled}));else if(time)draft.value.conditions.splice(index,1,automationTimeConditionAction({...time,enabled}));else if(config)draft.value.conditions.splice(index,1,automationDeviceConditionAction(config.deviceId,enabled,config.relation,config.conditions,config.schemaVersion))}
function conditionSummary(node:AutomationNode){const alarm=automationAlarmCondition(node);if(alarm)return automationAlarmConditionSummary(alarm,names.value.get(alarm.deviceId),alarmNames.value.get(alarm.alarmRuleId));const time=automationTimeCondition(node);if(time)return automationTimeConditionSummary(time);const c=automationDeviceCondition(node);return c?`${names.value.get(c.deviceId)||c.deviceId} · ${c.conditions.map(automationCurrentConditionText).join(c.relation==='ALL'?' 且 ':' 或 ')}`:'原有条件配置保持不变'}
function choosePicker(){if(picker.value==='trigger')chooseTrigger();else if(picker.value==='condition')chooseCondition();else chooseAction()}
function saveAction(node:AutomationNode,name:string,taskName?:string){const editor=actionEditor.value,config=automationTargetAction(node),scene=automationSceneRun(node),task=automationTaskRun(node);if(!editor||formBlocked.value||!config&&!scene&&!task)return;const next={key:editor.index===undefined?crypto.randomUUID():draft.value.actions[editor.index]!.key,node:cloneAutomationValue(node)};if(editor.index===undefined)draft.value.actions.push(next);else draft.value.actions.splice(editor.index,1,next);if(config)names.value=new Map(names.value).set(config.deviceId,name);else if(scene)names.value=new Map(names.value).set(scene.sceneId,name);else if(task){names.value=new Map(names.value).set(task.deviceId,name);if(taskName?.trim())taskNames.value=new Map(taskNames.value).set(task.taskId,taskName.trim())}actionEditor.value=undefined;error.value=''}
function chooseAction(purpose:'downlink'|'cloud-update'|'scene'|'task'='downlink'){if(!formBlocked.value){picker.value=undefined;actionEditor.value={purpose}}}
function editAction(index:number){const node=draft.value.actions[index]?.node;if(formBlocked.value||!node)return;const scene=automationSceneRun(node);if(scene){actionEditor.value={index,node:cloneAutomationValue(node),purpose:'scene'};return}const task=automationTaskRun(node);if(task){actionEditor.value={index,node:cloneAutomationValue(node),purpose:'task'};return}if(automationTargetAction(node))actionEditor.value={index,node:cloneAutomationValue(node),purpose:(automationCloudAction(node)||automationCloudTransformAction(node))?'cloud-update':'downlink'}}
function move(from:number,to:number){if(formBlocked.value||from<0||to<0||from>=draft.value.actions.length||to>=draft.value.actions.length)return;const values=draft.value.actions.slice(),row=values.splice(from,1)[0]!;values.splice(to,0,row);draft.value.actions=values}
