function drop(index:number,event:DragEvent){event.preventDefault();if(dragged)move(draft.value.actions.findIndex(row=>row.key===dragged),index);dragged=''}
function valueText(value:unknown){if(value instanceof ExactDecimal){try{return writePreprocessJson(value,true)}catch{return value.canonical()}}return typeof value==='string'?value:automationSignature(value)}
const triggerSummary=computed(()=>{const p=automationPropertyTrigger(draft.value.triggerConfig);if(p)return `${names.value.get(p.deviceId)||p.deviceId} · ${p.conditions.map(c=>`${c.propertyKey} ${automationOperatorLabels[c.operator]} ${valueText(c.value)}`).join(p.relation==='ALL'?' 且 ':' 或 ')}${p.durationSeconds>0?' · 持续'+automationDurationLabel(p.durationSeconds):''}`;const device=sourceDevice(draft.value.triggerConfig);return device?names.value.get(device)||device:'原有触发项配置保持不变'})
const triggerLabel=computed(()=>draft.value.triggerType==='PROPERTY_REPORTED'||draft.value.triggerType==='PROPERTY_CHANGED'?'设备属性变化':draft.value.triggerType==='ONE_SHOT'?'日期时间':draft.value.triggerType==='CRON'?'重复时间':'已有触发器')
function reportTriggerSummary(row:AutomationReportTrigger){const value=automationReportTriggerValue(row),predicate=automationPropertyTrigger(value),source=automationPropertySourceSelection(value),parts=[names.value.get(row.deviceId)||row.deviceId];if('sourceSelection' in row&&source&&source!=='ALL')parts.push(automationSourceLabels[source]);if(predicate?.conditions.length)parts.push(predicate.conditions.map(c=>`${c.propertyKey} ${automationOperatorLabels[c.operator]} ${valueText(c.value)}`).join(predicate.relation==='ALL'?' 且 ':' 或 '));if(predicate&&predicate.durationSeconds>0)parts.push('持续'+automationDurationLabel(predicate.durationSeconds));return parts.join(' · ')}
