function assertState(value:Intent,definition:Schema<'AutomationView'>){if(definition.id!==value.automationId||cas(definition.version)!==value.expectedFinalCAS||definition.status!==value.expectedStatus||value.expectedStatus==='DRAFT'&&definition.activeVersionId!=null||value.expectedStatus!=='DRAFT'&&(!definition.activeVersionId||definition.activeVersionId===value.previousActiveVersionId||value.selectedVersionId&&definition.activeVersionId!==value.selectedVersionId))throw new Error('自动化当前状态尚未与原保存意图一致；未重复提交。')}
async function readFinal(value:Intent){
