}
async function prepareCreate(value:Intent){
 if(value.mode!=='create'||!value.automationId)throw new Error('自动化创建上下文不完整')
 const first=await readAutomation(value.project,value.automationId),version=await readAutomationLatest(value.project,value.automationId),last=await readAutomation(value.project,value.automationId)
 if(first.id!==value.automationId||first.version!==1||last.version!==1||first.status!=='DRAFT'||last.status!=='DRAFT'||first.activeVersionId!=null||last.activeVersionId!=null||!version.id||value.selectedVersionId&&version.id!==value.selectedVersionId)throw new Error('自动化创建结果尚未与原意图一致；未重复提交。')
 assertAutomationContent(value.body,last,version);value.selectedVersionId=version.id;if(value.enabled)value.stage='activation'
}
function knownRejection(cause:unknown):cause is ApiError{return cause instanceof ApiError&&!cause.outcomeUnknown&&[400,401,403,404,409,422,429].includes(cause.status)}
async function activate(value:Intent){
 if(value.mode!=='create'||!value.automationId||!value.selectedVersionId||value.stateSent)throw new Error('该次启用结果应只读核对')
 value.stateSent=true
 let response:Schema<'AutomationView'>
 try{response=await activateAutomation(value.project,value.automationId,value.selectedVersionId,1)}catch(cause){if(knownRejection(cause))value.stateSent=false;throw cause}
 assertState(value,response);await readFinal(value)
}
async function finish(){const saved=intent.value?.automationId;if(!saved)throw new Error('自动化标识尚待核对');intent.value=undefined;pending.value=false;busy.value=false;error.value='';await router.push(`/rules/automations/${saved}`)}
async function save(){
 if(formBlocked.value||picker.value||triggerEditor.value||conditionEditor.value||actionEditor.value)return
 let value:Intent
 try{const body=automationDraftBody(draft.value),mode=editing.value?'atomic-edit':'create',before=mode==='atomic-edit'?cas(base.value?.version):0,enabled=draft.value.enabled,previousActiveVersionId=base.value?.activeVersionId??null;if(mode==='atomic-edit'&&!baseVersion.value?.id)throw new Error('自动化原版本尚未完整读取');value={mode,project:projectId.value,automationId:mode==='atomic-edit'?id.value:undefined,body,enabled,before,expectedFinalCAS:cas(before+(mode==='create'?(enabled?2:1):enabled?2:previousActiveVersionId?3:1)),expectedStatus:enabled?'ACTIVE':previousActiveVersionId?'PAUSED':'DRAFT',previousVersionId:baseVersion.value?.id,previousActiveVersionId,stage:'definition',stateSent:false}}catch(cause){error.value=errorMessage(cause);return}
 intent.value=value;busy.value=true;error.value='';const token=turn,epoch=identityEpoch();let accepted=false
 try{
  const response=value.mode==='create'?await createAutomation(value.project,value.body):await reviseAutomation(value.project,value.automationId!,value.body,value.before,value.enabled);accepted=true;if(!current(token,value.project,epoch))return
  if(value.mode==='atomic-edit'){assertState(value,response);if(response.activeVersionId)value.selectedVersionId=response.activeVersionId;await readFinal(value)}
  else{if(!definitionUuid(response.id)||response.version!==1||response.status!=='DRAFT'||response.activeVersionId!=null)throw new Error('自动化创建回执不完整，请只读核对');value.automationId=response.id;await prepareCreate(value);if(value.enabled){if(!current(token,value.project,epoch))return;if(!writable.value)throw new Error('项目当前不可修改，启用尚未提交');await activate(value)}}
  if(current(token,value.project,epoch))await finish()
 }catch(cause){if(current(token,value.project,epoch)&&!(cause instanceof IdentityChanged)){const known=!accepted&&knownRejection(cause),activationRejected=accepted&&value.mode==='create'&&value.stage==='activation'&&!value.stateSent&&knownRejection(cause);pending.value=!known&&!activationRejected;error.value=errorMessage(cause);if(known){intent.value=undefined;conflict.value=cause instanceof ApiError&&cause.status===409}}}finally{if(current(token,value.project,epoch))busy.value=false}
