 try{
  if(value.mode==='atomic-edit')await readFinal(value)
  else if(value.stage==='activation'&&value.stateSent)await readFinal(value)
  else{if(!value.automationId)value.automationId=(await findAutomationByName(value.project,value.body.name)).id;if(!value.automationId)throw new Error('原自动化仍待核对');await prepareCreate(value);if(value.enabled){if(current(token,value.project,epoch)){pending.value=false;error.value='已核对当前内容，启用尚未提交，请继续完成。'}return}}
  if(current(token,value.project,epoch))await finish()
