async function continueActivation(){const value=intent.value;if(!value||value.mode!=='create'||value.stateSent||pending.value||busy.value||!writable.value)return;const token=turn,epoch=identityEpoch();busy.value=true;try{await activate(value);if(current(token,value.project,epoch))await finish()}catch(cause){if(current(token,value.project,epoch)){pending.value=!(knownRejection(cause)&&!value.stateSent);error.value=errorMessage(cause)}}finally{if(current(token,value.project,epoch))busy.value=false}}
