<template><main class="tl-page automation-editor-page"><PageHeader :title="editing?'编辑自动化':'创建自动化'" back @back="back"/><AsyncState :forbidden="!allowed" :loading="loading"><el-alert v-if="error" :title="error" type="warning" :closable="false"><el-button v-if="pending" :disabled="busy" @click="verify">重新读取核对</el-button><el-button v-else-if="intent" :disabled="busy||!writable" @click="continueActivation">继续完成</el-button><el-button v-else-if="conflict||editing&&!base" :disabled="busy" @click="load">重新读取自动化</el-button></el-alert>
 <el-form v-if="!editing||base||intent" label-position="top" :disabled="formBlocked" @submit.prevent><section v-if="editing||step===1">
  <h2>设置触发器</h2><p class="automation-tips">可添加多个触发器，满足任一触发器即可触发自动化。</p><div v-if="mixed" class="automation-item-list"><div v-for="(row,index) in mixed.triggers" :key="index" class="automation-item" :class="{'is-disabled':!row.enabled}"><span class="automation-item-icon" :style="{background:automationMixedPresentation(row.kind).background,color:automationMixedPresentation(row.kind).color}"><ReferenceIcon :glyph="automationMixedPresentation(row.kind).glyph"/></span><div class="automation-item-content"><div class="automation-condition-name"><strong>{{automationMixedPresentation(row.kind).label}}</strong><el-switch :model-value="row.enabled" :aria-label="`启用触发器 ${index+1}`" title="启用/停用触发器" size="small" :disabled="formBlocked" @update:model-value="changeTriggerEnabled(index,$event)"/></div><p>{{mixedTriggerSummary(row)}}</p></div><div class="automation-item-ops"><el-button :icon="Edit" size="small" :aria-label="`编辑触发器 ${index+1}`" :disabled="formBlocked" @click="editTrigger(index)"/><el-button :icon="Delete" size="small" type="danger" :aria-label="`移除触发器 ${index+1}`" :disabled="formBlocked" @click="removeTrigger(index)"/></div></div></div><div v-else-if="triggerRows" class="automation-item-list"><div v-for="(row,index) in triggerRows" :key="index" class="automation-item automation-trigger-item" :class="{'is-disabled':!row.enabled}"><span class="automation-item-icon" :style="{background:automationTriggerPresentation.background,color:automationTriggerPresentation.color}"><ReferenceIcon :glyph="automationTriggerPresentation.glyph"/></span><div class="automation-item-content"><div class="automation-condition-name"><strong>{{automationTriggerPresentation.label}}</strong><el-switch :model-value="row.enabled" :aria-label="`启用触发器 ${index+1}`" title="启用/停用触发器" size="small" :disabled="formBlocked" @update:model-value="changeTriggerEnabled(index,$event)"/></div><p>{{reportTriggerSummary(row)}}</p></div><div class="automation-item-ops"><el-button :icon="Edit" size="small" :aria-lab