  <section class="automation-section"><h2>设置条件（可选）</h2><p class="automation-tips">条件可用于限制自动化触发后是否执行。若设置多个条件，所有条件必须同时满足才会执行。</p><div v-if="draft.conditions.length" class="automation-item-list"><div v-for="(node,index) in draft.conditions" :key="index" class="automation-item" :class="{'is-disabled':conditionEnabled(node)===false}"><span v-if="conditionEnabled(node)!==undefined" class="automation-item-icon" :style="{background:conditionPresentation(node).background,color:conditionPresentation(node).color}"><ReferenceIcon :glyph="conditionPresentation(node).glyph"/></span><div class="automation-item-content"><div class="automation-condition-name"><strong>{{conditionEnabled(node)!==undefined?conditionPresentation(node).label:'已有条件'}}</strong><el-switch v-if="conditionEnabled(node)!==undefined" :model-value="conditionEnabled(node)" :aria-label="`启用条件 ${index+1}`" title="启用/禁用条件" size="small" :disabled="formBlocked" @update:model-value="changeConditionEnabled(index,$event)"/></div><p>{{conditionSummary(node)}}</p></div><div v-if="conditionEnabled(node)!==undefined" class="automation-item-ops"><el-button :icon="Edit" size="small" :aria-label="`编辑条件 ${index+1}`" :disabled="formBlocked" @click="editCondition(index)"/><el-button :icon="Delete" size="small" type="danger" :aria-label="`${automationAlarmCondition(node)?'移除告警条件':automationTimeCondition(node)?'移除时间条件':'移除设备条件'} ${index+1}`" :disabled="formBlocked" @click="draft.conditions.splice(index,1)"/></div></div></div><div v-else class="automation-empty">暂无条件</div><el-button plain type="primary" class="automation-add" :disabled="formBlocked||draft.conditions.length>=32" @click="picker='condition'">添加条件</el-button></section>
  <section class="automation-section"><h2>设置动作</h2><p class="automation-tips">自动化触发并通过满足条件后，将按顺序执行这些动作。</p><div v-if="draft.actions.length" class="automation-item-list"><div v-for="(row,index) in draft.actions" :key="row.key" class="automation-item" @dragover.prevent @drop="drop(index,$event)"><span class="automation-item-icon" :style="{background:automationActionStyle(row.node).background,color:automationActionStyle(row.node).color}"><ReferenceIcon :glyph="automationActionStyle(row.node).glyph"/></span><div class="automation-item-content"><strong>{{automationTargetAction(row.node)||automationSceneRun(row.node)||automationTaskRun(row.node)?automationActionStyle(row.node).label:'已有操作'}}</strong><p>{{actionSummary(row.node)}}</p></div><div class="automation-item-ops"><el-button :icon="Sort" size="small" :aria-label="`调整动作顺序 ${index+1}`" :disabled="formBlocked" :draggable="!formBlocked" @dragstart="startDrag(index,$event)" @dragend="dragged=''" @keydown.up.prevent="move(index,index-1)" @keydown.down.prevent="move(index,index+1)"/><el-button v-if="automationTargetAction(row.node)||automationSceneRun(row.node)||automationTaskRun(row.node)" :icon="Edit" size="small" :aria-label="`编辑动作 ${index+1}`" :disabled="formBlocked" @click="editAction(index)"/><el-button :icon="Delete" size="small" type="danger" :aria-label="`移除动作 ${index+1}`" :disabled="formBlocked" @click="draft.actions.splice(index,1)"/></div></div></div><div v-else class="automation-empty">暂无动作</div><el-button plain type="primary" class="automation-add" :disabled="formBlocked" @click="picker='action'">添加动作</el-button></section>
  <section v-if="mixed" class="automation-section"><h2>其它设置</h2><AutomationTimezoneFields :value="mixed" :project-timezone="currentProject?.timezone" :disabled="formBlocked" @change="changeTimezone"/></section>
  <div class="automation-footer"><template v-if="editing"><el-button type="primary" :disabled="formBlocked" :loading="busy" @click="save">保存</el-button><el-button :disabled="blocked" @click="back">取消</el-button></template><el-button v-else type="primary" :disabled="formBlocked" @click="next">下一步</el-button></div>
 </section><section v-else><el-form-item label="名称"><el-input v-model="draft.name" class="automation-metadata" aria-label="自动化名称" placeholder="请输入自动化名称" maxlength="40" show-word-limit :disabled="formBlocked"/></el-form-item><el-form-item label="描述"><el-input v-model="draft.description" class="automation-metadata" aria-label="自动化描述" placeholder="请输入描述（可选）" type="textarea" :rows="4" maxlength="200" show-word-limit :disabled="formBlocked"/></el-form-item><RuleTagsEditor v-model="draft.tags" class="automation-tags" aria-label="自动化标签" :disabled="formBlocked" :maximum-rows="null"/><el-form-item label="启用自动化"><el-switch v-model="draft.enabled" aria-label="启用自动化" :disabled="formBlocked"/></el-form-item><div class="automation-save-footer"><el-button :disabled="formBlocked" @click="step=1">上一步</el-button><el-button type="primary" :disabled="formBlocked" :loading="busy" @click="save">创建</el-button></div></section></el-form>
 </AsyncState><el-dialog :model-value="!!picker" :title="picker==='trigger'?'配置触发项':picker==='condition'?'选择条件类型':'添加动作'" :width="picker==='condition'?'600px':'650px'" :lock-scroll="false" :close-on-click-modal="false" :close-on-press-escape="!blocked" :show-close="!blocked" append-to-body @update:model-value="!blocked&&(picker=undefined)"><template v-if="picker==='trigger'"><button v-for="kind in automationMixedKinds.filter(value=>value!=='PROPERTY_CHANGED')" :key="kind" class="automation-type-picker" type="button" :aria-label="automationMixedPresentation(kind).label" :disabled="formBlocked" @click="chooseTrigger(kind)"><span :style="{background:automationMixedPresentation(kind).background,color:automationMixedPresentation(kind).color}"><ReferenceIcon :glyph="automationMixedPresentation(kind).glyph"/></span><div><strong>{{automationMixedPresentation(kind).label}}</strong><p>{{automationMixedPresentation(kind).description}}</p></div><el-icon><ArrowRight/></el-icon></button></template><button v-if="picker==='condition'" class="automation-type-picker" type="button" aria-label="时间范围" :disabled="formBlocked" @click="chooseCondition(true)"><span :style="{background:automationTimeConditionPresentation.background,color:automationTimeConditionPresentation.color}"><ReferenceIcon :glyph="automationTimeConditionPresentation.glyph"/></span><div><strong>{{automationTimeConditionPresentation.label}}</strong><p>{{automationTimeConditionPresentation.description}}</p></div><el-icon><ArrowRight/></el-icon></button><button class="automation-type-picker" type="button" :aria-label="pickerPresentation.label" :disabled="formBlocked" @click="choosePicker"><span :style="{background:pickerPresentation.background,color:pickerPresentation.color}"><ReferenceIcon :glyph="pickerPresentation.glyph"/></span><div><strong>{{pickerPresentation.label}}</strong><p>{{pickerPresentation.description}}</p></div><el-icon><ArrowRight/></el-icon></button><button v-if="picker==='action'" class="automation-type-picker" type="button" aria-label="更新属性" :disabled="formBlocked" @click="chooseAction('cloud-update')"><span :style="{background:automationCloudPresentation.background,color:automationCloudPresentation.color}"><ReferenceIcon :glyph="automationCloudPresentation.glyph"/></span><div><strong>{{automationCloudPresentation.label}}</strong><p>{{automationCloudPresentation.description}}</p></div><el-icon><ArrowRight/></el-icon></button><button v-if="picker==='action'" class="automation-type-picker" type="button" aria-label="执行场景" :disabled="formBlocked" @click="chooseAction('scene')"><span :style="{background:automationScenePresentation.background,color:automationScenePresentation.color}"><ReferenceIcon :glyph="automationScenePresentation.glyph"/></span><div><strong>{{automationScenePresentation.label}}</strong><p>{{automationScenePresentation.description}}</p></div><el-icon><ArrowRight/></el-icon></button><button v-if="picker==='action'" class="automation-type-picker" type="button" aria-label="执行任务" :disabled="formBlocked" @click="chooseAction('task')"><span :style="{background:automationTaskPresentation.background,color:automationTaskPresentation.color}"><ReferenceIcon :glyph="automationTaskPresentation.glyph"/></span><div><strong>{{automationTaskPresentation.label}}</strong><p>{{automationTaskPresentation.description}}</p></div><el-icon><ArrowRight/></el-icon></button><button v-if="picker==='condition'" class="automation-type-picker" type="button" aria-label="设备告警状态" :disabled="formBlocked" @click="chooseAlarmCondition"><span :style="{background:automationAlarmConditionPresentation.background,color:automationAlarmConditionPresentation.color}"><ReferenceIcon :glyph="automationAlarmConditionPresentation.glyph"/></span><div><strong>{{automationAlarmConditionPresentation.label}}</strong><p>{{automationAlarmConditionPresentation.description}}</p></div><el-icon><ArrowRight/></el-icon></button></el-dialog>
